const fs = require("fs");
const path = require("path");

const target = process.argv[2] || path.join(__dirname, "README.md");
const text = fs.readFileSync(target, "utf8");

const needle = "TODO";
let count = 0;
let index = text.indexOf(needle);
while (index !== -1) {
  count += 1;
  index = text.indexOf(needle, index + needle.length);
}

console.log(count);

